        "physique": "Shirtless, displaying a highly athletic, lean, and muscular torso with sharply defined sixpack abdominal muscles and chest.",
        "facial_features": {
            "gaze": "Direct, piercing look toward the lens.",
            "eyes": "Striking, clear bluegreen eyes.",
            "eyebrows": "Defined, dark, groomed.",
            "nose": "Symmetrical, straight nose bridge.",
            "lips": "Natural pinkish, closed in a relaxed expression.",
            "jawline": "Sharp, cleanshaven jaw."
        },
        "hair": "Messy, textured dark brown curls on top with a clean undercut fade on the sides.",
        "jewelry": "A thin black cord necklace with a small geometric pendant resting on his bare collarbone."
    },
    "subject_2_white_haired_man": {
        "facial_features": {
            "expression": "A cool, confident, relaxed masculine expression. Mouth is closed in a neutral look, avoiding any puckering or kissyface expressions.",
            "gaze": "Steady, selfassured gaze directly into the lens.",
            "eyes": "Dark brown eyes with natural, relaxed eyelids.",
            "skin_complexion": "Fair, smooth olive skin with realistic micropores and a subtle shadow of cleanshaven stubble."
        },
        "hair": {
            "color": "Vibrant, highcontrast dyed platinumwhite hair.",
            "style": "Short, textured spiky crop on top, with a clean skinfade undercut on the sides where natural dark hair is visible near the ears."
